def max_rec(xs, lo, hi):
    if lo == hi:
        return xs[lo]
    mid = (lo + hi) // 2
    return max(max_rec(xs, lo, mid), max_rec(xs, mid + 1, hi))


def power_fast(x, n):
    if n == 0:
        return 1, 0
    if n == 1:
        return x, 0
    h, m = power_fast(x, n // 2)
    if n % 2 == 0:
        return h * h, m + 1
    return h * h * x, m + 2

